actions.script:
const projectId = ec.context.get('projectTabId')
if (!projectId) ec.message.addError(ec.l10n.localize('Project not available'))
const out = projectId ? ec.service.sync().name('ironstone.projects.ProjectServices.setup#ProjectDocs').parameters({workEffortId: projectId, storage: 'db'}).call() || {} : {}
if (!ec.message.hasError() && out.message) ec.message.addMessage(out.message, 'success')

// in a project's Docs tab: its documentation space only, and the links stay in the tab
projectMode = !!ec.context.get('inProjectDetail')
knowledgeUrl = projectMode ? '../Docs' : '//Commons/Knowledge'
docs = null; linkedList = []; projectNote = ''; canSetupDocs = false
let projectSpaceId = null
if (projectMode) {
    const projectId = ec.context.get('projectTabId')
    docs = projectId ? ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectDocs').parameters({workEffortId: projectId}).call()?.docs || null : null
    ec.message.clearErrors()
    if (!docs) projectNote = ec.l10n.localize('This project is not available.')
    else {
        projectSpaceId = docs.wikiSpaceId && docs.canView ? docs.wikiSpaceId : null
        if (!docs.wikiSpaceId) projectNote = ec.l10n.localize('This project has no documentation space yet.')
        else if (docs.missing) projectNote = ec.l10n.localize('The documentation space of this project is gone.')
        else if (!docs.canView) projectNote = ec.l10n.localize('You may not read this project\'s documentation.')
        canSetupDocs = !docs.wikiSpaceId && !!docs.canSetup
        linkedList = Array.from(docs.linkedList || []).map((link) => ({title: link.title, spaceName: link.spaceName, linkSpaceId: link.wikiSpaceId,
            linkPath: link.pagePath}))
    }
}
const setup = projectMode && !projectSpaceId ? {spaceList: []}
        : ec.service.sync().name('ironstone.commons.KnowledgeServices.get#KnowledgeSetup').parameter('wikiSpaceId', projectMode ? projectSpaceId : (wikiSpaceId || null)).call()
// in the project mode a page of a linked space opens too (wikiSpaceId given), else the project's space
const openSpaceId = projectMode ? (wikiSpaceId || projectSpaceId) : (wikiSpaceId || setup.defaultWikiSpaceId || null)
// in Customer Service (impl-customer-service P12) the spaces of the organization's knowledge sources only, as Knowledge.qvue's
const serviceSpaceIds = ec.context.get('inCustomerService') ? Array.from(ec.service.sync().name('ironstone.customerservice.KnowledgeServices.get#KnowledgeContext')
        .parameters({appRoot: 'CustomerService'}).call()?.knowledgeContext?.spaceIds || []) : null
spaceList = Array.from(setup.spaceList || []).filter((space) => !projectMode || space.wikiSpaceId === projectSpaceId)
        .filter((space) => !serviceSpaceIds || serviceSpaceIds.includes(space.wikiSpaceId))
        .map((space) => ({spaceId: space.wikiSpaceId, description: space.description || space.wikiSpaceId,
            storageText: space.storageText || '', openText: !wikiPageId && space.wikiSpaceId === openSpaceId ? ec.l10n.localize('Open') : ''}))
page = null
crumbList = []
childList = []
changeText = ''
if (!ec.message.hasError() && (wikiPageId || openSpaceId)) {
    const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageView').parameters(wikiPageId ? {wikiPageId: wikiPageId}
            : {wikiSpaceId: openSpaceId, pagePath: pagePath || ''}).call()
    if (!ec.message.hasError() && out.page) {
        page = out.page
        crumbList = [{label: page.spaceDescription || page.wikiSpaceId, crumbPath: ''}].concat(Array.from(page.breadcrumbs || [])
                .map((crumb) => ({label: crumb.label, crumbPath: crumb.pagePath})))
        if (page.isRoot) crumbList = []
        const change = page.lastChange
        changeText = change ? [change.dateText, change.userName, change.note].filter((part) => part).join(' · ') : ''
        if (page.exists) {
            const children = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageChildren').parameters({wikiSpaceId: page.wikiSpaceId,
                pagePath: page.pagePath || ''}).call()
            if (!ec.message.hasError()) childList = Array.from(children.childList || []).map((child) => ({childSpaceId: page.wikiSpaceId,
                childPath: child.pagePath, name: child.name + (child.hasChildren ? ' …' : ''), restrictedText: child.restricted ? ec.l10n.localize('Restricted') : ''}))
        }
    }
}
